#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <filesystem>
#include <cstdlib>
#include <getopt.h>
#include <reflex/input.h>

#include "Lexer.hpp"      // in build/compiler/ (generated) or grammar/ (wrapper)
#include "asn1.tab.hh"   // generated by Bison into build/compiler/
#include "ast/Module.hpp"
#include "sema/Resolver.hpp"
#include "sema/ContainedFields.hpp"
#include "codegen/Generator.hpp"
#include "codegen/CppBackend.hpp"
#include "codegen/RustBackend.hpp"

namespace fs = std::filesystem;

static const struct option long_opts[] = {
    {"help",                 no_argument,       nullptr, 'h'},
    {"fallow-newer-modules", no_argument,       nullptr, 'A'},
    {"fbless-SIZE",          no_argument,       nullptr, 'B'},
    {"fprefix",              required_argument, nullptr, 'P'},
    {"pdu",                  required_argument, nullptr, 'D'},
    {"integer-type",         required_argument, nullptr, 'I'},
    {"target",               required_argument, nullptr, 'T'},
    {"stdlib-dir",           required_argument, nullptr, 'S'},
    {"container-config",     required_argument, nullptr, 'C'},
    {"list-contained",       no_argument,       nullptr, 'L'},
    {nullptr, 0, nullptr, 0}
};

#ifndef ASN1CPP_STDLIB_DIR
#define ASN1CPP_STDLIB_DIR ""
#endif

// X.681 Annex A/B (TYPE-IDENTIFIER, ABSTRACT-SYNTAX) and X.208 §34
// (EXTERNAL) are implicitly available in every module without an
// IMPORTS clause. Rather than hand-building their AST, parse the real
// .asn1 module that defines them (verbatim copy of asn1c's own
// skeletons/standard-modules/ASN1C-UsefulInformationObjectClasses.asn1 —
// asn1c is this project's ground-truth reference compiler) through the
// same grammar as any user file, before the user's own modules.
static const char* kStdlibModuleFile = "ASN1C-UsefulInformationObjectClasses.asn1";

static void print_help(const char* prog) {
    std::cout <<
        "Usage: " << prog << " [options] file.asn1 [file2.asn1 ...]\n"
        "\n"
        "Options:\n"
        "  -h, --help                  Show this help and exit\n"
        "  -E                          Parse and check only; skip code generation\n"
        "  -o <dir>                    Output directory (default: generated)\n"
        "  -fallow-newer-modules       Accept module version mismatches silently\n"
        "  -fbless-SIZE                (Non-standard) Accept SIZE() on INTEGER/ENUMERATED\n"
        "  -fprefix=<name>             Wrap all generated types in namespace <name>.\n"
        "                              (asn1c compatibility flag — asn1c prepends <name>\n"
        "                              as a C identifier prefix; asn1cpp uses a C++ namespace\n"
        "                              instead, which is idiomatic and collision-safe.)\n"
        "  -pdu=<TypeName>             Generate only <TypeName> and its transitive dependencies.\n"
        "                              May be specified multiple times for multiple roots.\n"
        "  --container-config=<file>   JSON sidecar naming OCTET STRING fields that hold the\n"
        "                              encoding of another type, and how to decode them\n"
        "                              (see doc/book.md, \"Contained values\").\n"
        "  --list-contained            Print every contained field (CONTAINING constraints\n"
        "                              and sidecar entries) with its settings.\n"
        "                              Without -pdu, all types in all modules are generated.\n"
        "                              -pdu=all is accepted as an alias for the default.\n"
        "  --integer-type=<kind>       Integer storage: int64 (default), uint64,\n"
        "                              int128 (unimplemented), arbitrary (unimplemented)\n"
        "  --target=<lang>             Output language: cpp (default) or rust (WIP).\n"
        "  --stdlib-dir=<dir>          Directory containing " << kStdlibModuleFile << "\n"
        "                              (X.681 TYPE-IDENTIFIER/ABSTRACT-SYNTAX + X.208\n"
        "                              EXTERNAL, auto-included in every module).\n"
        "                              Default: " ASN1CPP_STDLIB_DIR "\n";
}

static void usage(const char* prog) {
    std::cerr << "Usage: " << prog
              << " [-E] [-o outdir] [-fallow-newer-modules] [-fbless-SIZE]"
                 " [-fprefix=<name>] [-pdu=<TypeName>]"
                 " [--integer-type=int64|uint64|int128|arbitrary]"
                 " [--target=cpp|rust] [--stdlib-dir=<dir>]"
                 " file.asn1 [file2.asn1 ...]\n"
                 "Try '" << prog << " --help' for more information.\n";
    std::exit(1);
}

/// @brief Applies a module's EXTENSIBILITY IMPLIED (X.680 §12): "equivalent
///        to the textual insertion of an extension marker ('...') in the
///        definition of each type in the module for which it is permitted",
///        at the last position where one is allowed. Appends a marker to
///        every SEQUENCE, SET and CHOICE member list and every ENUMERATED
///        value list that has none, nested inline types included, so the
///        rest of the compiler sees ordinary extensible types.
/// @param t A type (or member) definition of such a module.
static void imply_extensibility(asn1::ast::TypeDef& t) {
    using namespace asn1::ast;
    if (t.is_sequence() || t.is_set() || t.is_choice()) {
        for (auto& m : t.members)
            if (m && !m->is_extension_marker) imply_extensibility(*m);
        bool has_marker = false;
        for (const auto& m : t.members) has_marker = has_marker || (m && m->is_extension_marker);
        if (!has_marker) {
            auto marker = std::make_shared<TypeDef>();
            marker->is_extension_marker = true;
            t.members.push_back(marker);
        }
    }
    if (auto* sof = std::get_if<SequenceOfType>(&t.body); sof && sof->element) imply_extensibility(*sof->element);
    if (auto* sof = std::get_if<SetOfType>(&t.body); sof && sof->element) imply_extensibility(*sof->element);
    if (auto* bt = std::get_if<BuiltinType>(&t.body);
        bt && *bt == BuiltinType::Enumerated && !t.enum_values.empty()) {
        bool has_marker = false;
        for (const auto& ev : t.enum_values) has_marker = has_marker || ev.name == "...";
        if (!has_marker) t.enum_values.push_back(EnumValue{"...", std::nullopt});
    }
}

int main(int argc, char** argv) {
    std::string out_dir = "generated";
    std::string ns_prefix;
    std::vector<std::string> pdu_types;
    bool allow_newer_modules = false;
    bool bless_size = false;
    bool parse_only = false;
    asn1::codegen::IntStorageKind default_int_kind = asn1::codegen::IntStorageKind::S64;
    std::string target = "cpp";
    std::string stdlib_dir = ASN1CPP_STDLIB_DIR;
    std::vector<std::string> input_files;
    std::string container_config;
    bool list_contained = false;

    int opt;
    opterr = 0;  // suppress getopt's own diagnostics; usage() handles all errors
    while ((opt = getopt_long_only(argc, argv, "Eo:h", long_opts, nullptr)) != -1) {
        switch (opt) {
        case 'E': parse_only = true; break;
        case 'o': out_dir = optarg; break;
        case 'h': print_help(argv[0]); return 0;
        case 'A': allow_newer_modules = true; break;
        case 'P': ns_prefix = optarg; break;
        case 'D':
            if (std::string(optarg) != "all")
                pdu_types.push_back(optarg);
            break;
        case 'B':
            // Non-standard: accept SIZE() on INTEGER/ENUMERATED (asn1c compatibility).
            // X.680 §47.5.2 forbids this; the constraint is silently ignored in codegen.
            bless_size = true;
            break;
        case 'I': {
            std::string kind = optarg;
            if (kind == "int64") {
                default_int_kind = asn1::codegen::IntStorageKind::S64;
            } else if (kind == "uint64") {
                default_int_kind = asn1::codegen::IntStorageKind::U64;
            } else if (kind == "int128") {
                std::cerr << "warning: --integer-type=int128 is not yet implemented; using int64\n";
            } else if (kind == "arbitrary") {
                std::cerr << "warning: --integer-type=arbitrary is not yet implemented; using int64\n";
            } else {
                std::cerr << "error: unknown --integer-type value '" << kind << "'\n";
                usage(argv[0]);
            }
            break;
        }
        case 'T':
            target = optarg;
            if (target != "cpp" && target != "rust") {
                std::cerr << "error: unknown --target value '" << target << "' (expected cpp or rust)\n";
                usage(argv[0]);
            }
            break;
        case 'S':
            stdlib_dir = optarg;
            break;
        case 'C': container_config = optarg; break;
        case 'L': list_contained = true; break;
        default: usage(argv[0]);
        }
    }
    for (int i = optind; i < argc; ++i)
        input_files.push_back(argv[i]);
    if (input_files.empty()) usage(argv[0]);

    if (!ns_prefix.empty()) {
        auto valid_id = [](std::string_view s) {
            if (s.empty()) return false;
            if (!std::isalpha((unsigned char)s[0]) && s[0] != '_') return false;
            return std::all_of(s.begin(), s.end(), [](char c){
                return std::isalnum((unsigned char)c) || c == '_';
            });
        };
        if (!valid_id(ns_prefix)) {
            std::cerr << "error: -fprefix value '" << ns_prefix << "' is not a valid identifier\n";
            return 1;
        }
    }

    asn1::ast::ParseResult pr;

    if (!stdlib_dir.empty()) {
        fs::path stdlib_path = fs::path(stdlib_dir) / kStdlibModuleFile;
        std::ifstream stdlib_in(stdlib_path);
        if (!stdlib_in) {
            std::cerr << "error: cannot open predefined-classes module " << stdlib_path
                      << " (see --stdlib-dir)\n";
            return 1;
        }
        std::string stdlib_src((std::istreambuf_iterator<char>(stdlib_in)),
                                std::istreambuf_iterator<char>());
        Lexer stdlib_lexer(reflex::Input(stdlib_src), std::cerr);
        yy::parser stdlib_parser(stdlib_lexer, pr);
        if (stdlib_parser.parse() != 0) {
            std::cerr << "Parse error in " << stdlib_path << "\n";
            return 1;
        }
    }

    for (const auto& path : input_files) {
        std::ifstream in(path);
        if (!in) {
            std::cerr << "Cannot open " << path << "\n";
            return 1;
        }
        std::string src((std::istreambuf_iterator<char>(in)),
                         std::istreambuf_iterator<char>());

        Lexer lexer(reflex::Input(src), std::cerr);
        yy::parser parser(lexer, pr);
        if (parser.parse() != 0) {
            std::cerr << "Parse error in " << path << "\n";
            return 1;
        }
    }

    std::cout << "Parsed " << pr.modules.size() << " module(s).\n";
    for (const auto& mod : pr.modules)
        std::cout << "  Module: " << mod->name
                  << " (" << mod->assignments.size() << " assignments)\n";

    if (parse_only)
        return 0;

    for (auto& mod : pr.modules)
        if (mod->extensibility_implied)
            for (auto& t : mod->assignments)
                if (t) imply_extensibility(*t);

    asn1::sema::Resolver resolver;
    resolver.set_allow_newer_modules(allow_newer_modules);
    resolver.set_bless_size(bless_size);
    resolver.collect(pr);
    resolver.resolve_imports(pr);
    resolver.resolve_types(pr);
    resolver.resolve_class_field_refs(pr);
    resolver.resolve_parameterized_instantiations(pr);
    resolver.resolve_value_assignments(pr);

    for (const auto& w : resolver.warnings())
        std::cerr << "warning: " << w << "\n";
    if (!resolver.errors().empty()) {
        for (const auto& e : resolver.errors())
            std::cerr << "error: " << e << "\n";
        return 1;
    }

    asn1::sema::ContainedFields contained;
    {
        std::vector<std::string> cw, ce;
        if (!container_config.empty())
            contained.load_config(container_config, ce);
        if (ce.empty())
            contained.build(pr, resolver, cw, ce);
        for (const auto& w : cw) std::cerr << "warning: " << w << "\n";
        if (!ce.empty()) {
            for (const auto& e : ce) std::cerr << "error: " << e << "\n";
            return 1;
        }
    }
    if (list_contained) {
        for (const auto& f : contained.all()) {
            std::cout << "contained: " << f.module << "." << f.type << "." << f.field
                      << " -> " << f.inner_module << "." << f.inner_type
                      << " source=" << (f.from_constraint && f.from_config ? "CONTAINING+config"
                                        : f.from_constraint ? "CONTAINING" : "config")
                      << " encoding=" << asn1::sema::to_string(f.encoding)
                      << " decode=" << (f.decode == asn1::sema::ContainedDecode::Eager ? "eager" : "off")
                      << " decoder=" << f.decoder;
            if (f.when)
                std::cout << " when=" << f.when->member << "==" << f.when->text
                          << "(" << f.when->value << ")";
            std::cout << " on_error=" << (f.on_error == asn1::sema::ContainedOnError::Fail ? "fail" : "keep_raw")
                      << " xer=" << asn1::sema::to_string(f.xer)
                      << " jer=" << asn1::sema::to_string(f.jer) << "\n";
        }
        return 0;
    }

    asn1::codegen::CppBackend cpp_backend;
    asn1::codegen::RustBackend rust_backend;
    asn1::codegen::Backend& backend = (target == "rust")
        ? static_cast<asn1::codegen::Backend&>(rust_backend)
        : static_cast<asn1::codegen::Backend&>(cpp_backend);

    asn1::codegen::Generator gen(out_dir, resolver, backend);
    gen.set_default_int_kind(default_int_kind);
    if (!ns_prefix.empty()) gen.set_namespace(ns_prefix);
    for (const auto& t : pdu_types) gen.add_pdu_type(t);
    gen.set_contained_fields(&contained);
    gen.generate(pr);
    backend.finalize_output(out_dir);

    std::cout << "Generated " << (target == "rust" ? "Rust" : "C++") << " code in: " << out_dir << "/\n";
    return 0;
}
